// Validate YAML text with two parsers. Usage: node validate_yaml.js file...
const fs = require('fs');
const YAML = require('yaml');
const jsyaml = require('js-yaml');
const anyTag = (tag) => ['scalar','sequence','mapping'].map(kind =>
  new jsyaml.Type(tag, {kind, multi: true, construct: d => d}));
const schema = jsyaml.DEFAULT_SCHEMA.extend([
  ...anyTag('!vault'), ...anyTag('!ENV'), ...anyTag('!expr'),
  new jsyaml.Type('tag:yaml.org,2002:python/name:', {kind:'scalar', multi:true, construct: d => d}),
]);
function check(name, text) {
  const docs = YAML.parseAllDocuments(text, {version: '1.2', merge: true});
  let ok = true;
  const arr = Array.isArray(docs) ? docs : [docs];
  for (const d of arr) {
    for (const e of d.errors) { ok = false; console.log(`${name}: yaml ERROR ${e.message.split('\n')[0]}`); }
    for (const w of d.warnings) { if (!/Unresolved tag/.test(w.message)) console.log(`${name}: yaml warn ${w.message.split('\n')[0]}`); }
  }
  try { jsyaml.loadAll(text, () => {}, {schema}); }
  catch (e) { ok = false; console.log(`${name}: js-yaml ERROR ${e.message.split('\n')[0]}`); }
  return [ok, arr.length];
}
module.exports = { check };
if (require.main === module) {
  for (const f of process.argv.slice(2)) {
    const [ok, n] = check(f, fs.readFileSync(f, 'utf8'));
    console.log(`${f}: ${ok ? 'OK' : 'FAIL'} (${n} docs)`);
  }
}
