// Extract front matter, ```yaml fences and #| hashpipe blocks and validate them.
const fs = require('fs');
const { check } = require('./validate_yaml.js');
for (const f of process.argv.slice(2)) {
  const lines = fs.readFileSync(f, 'utf8').split('\n');
  const blocks = [];
  // front matter
  if (lines[0] === '---') {
    const end = lines.indexOf('---', 1);
    blocks.push(['front-matter@1', lines.slice(1, end).join('\n')]);
  }
  // yaml fences (any indentation, ``` or ~~~)
  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(/^(\s*)(`{3,}|~{3,})\s*\{?(yaml|yml)\b/);
    if (m) {
      const fence = m[2]; const body = [];
      let j = i + 1;
      for (; j < lines.length && !lines[j].trim().startsWith(fence); j++) body.push(lines[j].slice(m[1].length));
      blocks.push([`fence@${i + 1}`, body.join('\n')]);
      i = j;
    }
  }
  // hashpipe blocks: consecutive lines starting with '#|' (after optional indentation)
  for (let i = 0; i < lines.length; i++) {
    if (/^\s*#\|/.test(lines[i])) {
      const body = []; const start = i;
      while (i < lines.length && /^\s*#\|/.test(lines[i])) {
        body.push(lines[i].replace(/^\s*#\| ?/, ''));
        i++;
      }
      blocks.push([`hashpipe@${start + 1}`, body.join('\n')]);
    }
  }
  for (const [where, text] of blocks) {
    const [ok] = check(`${f}:${where}`, text);
    console.log(`${f.split('/').pop()}:${where}: ${ok ? 'OK' : 'FAIL'}`);
  }
}
